package capability
import("crypto/sha256";"encoding/hex";"encoding/json";"os";"path/filepath";"testing")
func TestLoadVerifiesExactDeploymentAndBytes(t *testing.T){root:=t.TempDir();provider:=filepath.Join(root,"provider.bin");content:=[]byte("exact-provider-bytes");if err:=os.WriteFile(provider,content,0700);err!=nil{t.Fatal(err)};hash:=sha256.Sum256(content);r:=Registry{Kind:RegistryKind,DeploymentID:"dep-1",Bindings:[]Binding{{Kind:BindingKind,CapabilityID:HostOpenCapability,ProviderID:"test-provider",ContractVersion:HostOpenContract,DeploymentID:"dep-1",ProviderKind:"executable",ExecutablePath:provider,IntegrityDigest:"sha256:"+hex.EncodeToString(hash[:]),VerificationStatus:"verified"}}};path:=filepath.Join(root,"capabilities.json");encoded,_:=json.Marshal(r);if err:=os.WriteFile(path,encoded,0600);err!=nil{t.Fatal(err)};b,err:=Load(path,"dep-1",HostOpenCapability);if err!=nil{t.Fatal(err)};if b.ProviderID!="test-provider"{t.Fatalf("binding=%+v",b)};if err:=os.WriteFile(provider,[]byte("tampered"),0700);err!=nil{t.Fatal(err)};if _,err:=Load(path,"dep-1",HostOpenCapability);err==nil{t.Fatal("tampered provider must fail")}}
